1284	///|
1285	fn diagnostic_output(
1286	  output : Bytes,
1287	  environment : Map[String, String],
1288	  protected_input? : String,
1289	  protect_all_input~ : Bool = false,
1290	  protected_secrets? : Array[String],
1291	  omitted~ : Bool = false,
1292	) -> String? {
1293	  if output.length() == 0 {
1294	    return if omitted {
1295	      Some("[error details incomplete or truncated]")
1296	    } else {
1297	      None
1298	    }
1299	  }
1300	  let limit = if output.length() > 8192 { 8192 } else { output.length() }
1301	  let incomplete = omitted || limit < output.length()
1302	  let text = @utf8.decode_lossy(output[:limit])
1303	  let safeguards : DiagnosticProtectedValues = {
1304	    secrets: [],
1305	    visited: 0,
1306	    incomplete: false,
1307	  }
1308	  if protected_input is Some(input) {
1309	    diagnostic_protected_values(
1310	      @json.parse(input),
1311	      safeguards,
1312	      text,
1313	      incomplete,
1314	      secret=protect_all_input,
1315	    ) catch {
1316	      _ => safeguards.incomplete = true
1317	    }
1318	  }
1319	  if safeguards.incomplete {
1320	    return Some(
1321	      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
1322	    )
1323	  }
1324	  Some(
1325	    diagnostic_text(
1326	      text,
1327	      environment~,
1328	      omitted=incomplete,
1329	      protected_secrets=safeguards.secrets + protected_secrets.unwrap_or([]),
1330	      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
1331	    ),
1332	  )
1333	}
