1408	async fn diagnostic_process_output(
1409	  program : String,
1410	  args : Array[String],
1411	  environment~ : Map[String, String],
1412	  cwd? : StringView,
1413	  stdin? : &@process.ProcessInput,
1414	  stdout_limit~ : Int32,
1415	  stderr_limit~ : Int32,
1416	) -> (Int32, Bytes, Bool, Bytes, Bool) {
1417	  let (out, stdout) = @process.read_from_process()
1418	  defer out.close()
1419	  let (err, stderr) = @process.read_from_process()
1420	  defer err.close()
1421	  @async.with_task_group(async fn(group) {
1422	    let child = @process.spawn(
1423	      group,
1424	      program,
1425	      args,
1426	      extra_env=environment,
1427	      inherit_env=false,
1428	      cwd?,
1429	      stdin?,
1430	      stdout~,
1431	      stderr~,
1432	    )
1433	    let output = DiagnosticCapture::new(stdout_limit)
1434	    let errors = DiagnosticCapture::new(stderr_limit)
1435	    group.spawn_bg(no_wait=true, async fn() { output.read(out) })
1436	    group.spawn_bg(no_wait=true, async fn() { errors.read(err) })
1437	    let status = child.wait()
1438	    if status == 0 {
1439	      while !output.finished {
1440	        @async.sleep(5)
1441	      }
1442	      wait_diagnostic_captures([errors])
1443	    } else {
1444	      wait_diagnostic_captures([output, errors])
1445	    }
1446	    (
1447	      status,
1448	      output.output.to_bytes(),
1449	      output.truncated || !output.finished,
1450	      errors.output.to_bytes(),
1451	      errors.truncated || !errors.finished,
1452	    )
1453	  })
1454	}
