199	///|
200	fn terminal_text(text : String) -> String? {
201	  let output = @buffer.Buffer(size_hint=256)
202	  let mut state = 0
203	  for c in text.iter() {
204	    match state {
205	      0 =>
206	        if c == '\u001b' {
207	          state = 1
208	        } else if c.to_int() < 32 && c != '\t' {
209	          return None
210	        } else {
211	          output.write_char_utf8(c)
212	        }
213	      1 =>
214	        if c == '[' {
215	          state = 2
216	        } else if c == ']' {
217	          state = 3
218	        } else {
219	          return None
220	        }
221	      2 => if c >= '@' && c <= '~' { state = 0 }
222	      3 => if c == '\u0007' { state = 0 } else if c == '\u001b' { state = 4 }
223	      _ => if c == '\\' { state = 0 } else { state = 3 }
224	    }
225	  }
226	  if state != 0 {
227	    None
228	  } else {
229	    Some(@utf8.decode_lossy(output.to_bytes()))
230	  }
231	}
