    47	///|
    48	fn object_field(
    49	  value : Json,
    50	  name : String,
    51	  location : String,
    52	) -> Json raise ConfigError {
    53	  match field(value, name) {
    54	    None => Json::empty_object()
    55	    Some(Json::Object(_) as object) => object
    56	    _ => raise InvalidConfig("\{location}.\{name} must be a mapping")
    57	  }
    58	}
