   126	///|
   127	pub fn interpolate(
   128	  value : String,
   129	  lookup : (String) -> String?,
   130	  location : String,
   131	) -> String raise ConfigError {
   132	  let output = StringBuilder()
   133	  let mut remaining = value
   134	  while remaining.split_once("${") is Some((prefix, expression)) {
   135	    output.write_string(prefix.to_owned())
   136	    guard expression.split_once("}") is Some((variable, suffix)) else {
   137	      raise InvalidConfig("\{location}: unterminated environment variable")
   138	    }
   139	    let text = variable.to_owned()
   140	    let required = text.has_suffix("?")
   141	    let name = if required { text[:text.length() - 1].to_owned() } else { text }
   142	    guard valid_env_name(name) else {
   143	      raise InvalidConfig("\{location}: invalid environment variable reference")
   144	    }
   145	    match lookup(name) {
   146	      Some(resolved) => output.write_string(resolved)
   147	      None if required =>
   148	        raise InvalidConfig(
   149	          "\{location}: environment variable \{name} is not defined",
   150	        )
   151	      None => ()
   152	    }
   153	    remaining = suffix.to_owned()
   154	  }
   155	  output.write_string(remaining)
   156	  output.to_string()
   157	}
