   159	///|
   160	pub fn resolve_settings(
   161	  document : Json,
   162	  recipe_id : String,
   163	  lookup : (String) -> String?,
   164	) -> Settings raise ConfigError {
   165	  resolve_settings_with_sources(document, recipe_id, lookup).0
   166	}
