   168	///|
   169	fn resolve_settings_with_sources(
   170	  document : Json,
   171	  recipe_id : String,
   172	  lookup : (String) -> String?,
   173	) -> (Settings, Array[String]) raise ConfigError {
   174	  let common = object_field(document, "devsy", "orca.yaml")
   175	  let recipes = match field(document, "environmentRecipes") {
   176	    Some(Json::Array(items)) => items
   177	    _ => raise InvalidConfig("orca.yaml.environmentRecipes must be an array")
   178	  }
   179	  let selected = recipes.filter(recipe => {
   180	    field(recipe, "id") == Some(Json::string(recipe_id))
   181	  })
   182	  guard selected.length() == 1 else {
   183	    raise InvalidConfig(
   184	      "Expected exactly one environment recipe named \{recipe_id}",
   185	    )
   186	  }
   187	  let specific = object_field(
   188	    selected[0],
   189	    "devsy",
   190	    "environmentRecipes.\{recipe_id}",
   191	  )
   192	  let profile_name = match string_field(specific, "profile", "recipe.devsy") {
   193	    Some(name) => Some(name)
   194	    None => string_field(common, "profile", "devsy")
   195	  }
   196	  let profiles = object_field(common, "profiles", "devsy")
   197	  let mut profile_location = "devsy.profiles"
   198	  let profile = match profile_name {
   199	    Some(raw_name) => {
   200	      let name = interpolate(raw_name, lookup, "devsy.profile")
   201	      profile_location = "devsy.profiles." + name
   202	      match field(profiles, name) {
   203	        Some(Json::Object(_) as value) => value
   204	        _ => raise InvalidConfig("Unknown devsy profile")
   205	      }
   206	    }
   207	    None => Json::empty_object()
   208	  }
   209	  let layers = [common, profile, specific]
   210	  let mut command = ["devsy"]
   211	  let mut home = None
   212	  let mut context = None
   213	  let mut build_ref = None
   214	  let mut connection = None
   215	  let mut codex_auth = false
   216	  let mut idle_timeout_ms = None
   217	  let mut idle_timeout_source = None
   218	  let args = []
   219	  let arg_sources = []
   220	  let server_env = Json::empty_object()
   221	  for index, layer in layers {
   222	    let location = [
   223	        "devsy",
   224	        profile_location,
   225	        "environmentRecipes." + recipe_id + ".devsy",
   226	      ][index]
   227	    if command_field(layer, location) is Some(raw) {
   228	      let expanded = raw.mapi((argument_index, argument) => {
   229	        interpolate(argument, lookup, "\{location}.command[\{argument_index}]")
   230	      })
   231	      let value = Json::empty_object()
   232	      set_field(value, "command", Json::array(expanded.map(Json::string)))
   233	      command = command_field(value, location).unwrap()
   234	    }
   235	    for
   236	      pair in [
   237	        ("home", string_field(layer, "home", location)),
   238	        ("context", string_field(layer, "context", location)),
   239	        ("buildRef", string_field(layer, "buildRef", location)),
   240	        ("connection", string_field(layer, "connection", location)),
   241	      ] {
   242	      let (name, value) = pair
   243	      if value is Some(raw) {
   244	        let expanded = interpolate(raw, lookup, "\{location}.\{name}")
   245	        match name {
   246	          "home" => home = Some(expanded)
   247	          "context" => context = Some(expanded)
   248	          "buildRef" => build_ref = Some(expanded)
   249	          _ => connection = Some(expanded)
   250	        }
   251	      }
   252	    }
   253	    for argument_index, argument in args_field(layer, location) {
   254	      args.push(
   255	        interpolate(argument, lookup, "\{location}.upArgs[\{argument_index}]"),
   256	      )
   257	      arg_sources.push(["common", "profile", "recipe"][index])
   258	    }
   259	    let server = object_field(layer, "orca-server", location)
   260	    let configured_env = object_field(server, "env", location + ".orca-server")
   261	    if configured_env is Json::Object(values) {
   262	      for name, value in values {
   263	        let setting_location = location + ".orca-server.env." + name
   264	        guard valid_env_name(name) else {
   265	          raise InvalidConfig(setting_location + " has an invalid name")
   266	        }
   267	        ignore(interpolate("${" + name + "}", _ => None, setting_location))
   268	        guard value is Json::String(text) && !text.contains("\u0000") else {
   269	          raise InvalidConfig(
   270	            setting_location + " must be a string without NUL",
   271	          )
   272	        }
   273	        let literal = interpolate(text, _ => Some(""), setting_location)
   274	        guard !(credential_field(name) && literal != "") &&
   275	          redact_credentials(text) == text else {
   276	          raise InvalidConfig(
   277	            setting_location + ": credential values must use remote references",
   278	          )
   279	        }
   280	        set_field(server_env, name, value)
   281	      }
   282	    }
   283	    let addons = object_field(layer, "addons", location)
   284	    if string_field(layer, "idleTimeout", location) is Some(raw) {
   285	      idle_timeout_ms = Some(
   286	        parse_idle_timeout(interpolate(raw, lookup, "\{location}.idleTimeout")) catch {
   287	          InvalidConfig(message) =>
   288	            raise InvalidConfig("\{location}.idleTimeout: " + message)
   289	        },
   290	      )
   291	      idle_timeout_source = Some(location + ".idleTimeout")
   292	    }
   293	    match field(addons, "codexAuth") {
   294	      None => ()
   295	      Some(Json::True) => codex_auth = true
   296	      Some(Json::False) => codex_auth = false
   297	      _ => raise InvalidConfig("\{location}.addons.codexAuth must be a boolean")
   298	    }
   299	  }
   300	  let connection = match connection {
   301	    Some("orca-server") => Server
   302	    Some("ssh") => Ssh
   303	    _ =>
   304	      raise InvalidConfig(
   305	        "devsy.connection must explicitly select orca-server or ssh",
   306	      )
   307	  }
   308	  (
   309	    {
   310	      connection,
   311	      command,
   312	      home,
   313	      context,
   314	      build_ref,
   315	      up_args: args,
   316	      codex_auth,
   317	      server_env,
   318	      idle_timeout_ms,
   319	      idle_timeout_source,
   320	    },
   321	    arg_sources,
   322	  )
   323	}
   324	
   325	///|
   326	fn field(value : Json, name : String) -> Json? {
   327	  if value is Json::Object(object) {
   328	    object.get(name)
   329	  } else {
   330	    None
   331	  }
   332	}
   333	
   334	///|
   335	fn observable_size(value : String) -> Bool {
   336	  value.length() > 0 &&
   337	  value.length() <= 64 &&
   338	  value
   339	  .iter()
   340	  .all(c => {
   341	    (c >= 'a' && c <= 'z') ||
   342	    (c >= 'A' && c <= 'Z') ||
   343	    (c >= '0' && c <= '9') ||
   344	    c == '.' ||
   345	    c == '-' ||
   346	    c == '_'
   347	  }) &&
   348	  [
   349	    "nano", "micro", "small", "medium", "large", "xlarge", "2xlarge", "4xlarge",
   350	    "8xlarge", "12xlarge", "16xlarge", "24xlarge", "32xlarge",
   351	  ]
   352	  .iter()
   353	  .any(size => {
   354	    value == size ||
   355	    value.has_suffix("." + size) ||
   356	    value.has_suffix("-" + size)
   357	  })
   358	}
   359	
   360	///|
   361	fn up_arguments_evidence(
   362	  args : Array[String],
   363	  sources : Array[String],
   364	) -> (Json, Bool) {
   365	  let selected : Array[Json] = []
   366	  let mut withheld = 0
   367	  let mut index = 0
   368	  while index < args.length() {
   369	    let argument = args[index]
   370	    let flag_source = sources[index]
   371	    let mut flag = argument
   372	    let mut value : String? = None
   373	    let mut value_source = sources[index]
   374	    if argument.split_once("=") is Some((name, attached)) {
   375	      flag = name.to_owned()
   376	      value = Some(attached.to_owned())
   377	    } else if ["--provider", "--platform", "--provider-option"].contains(
   378	        argument,
   379	      ) &&
   380	      index + 1 < args.length() {
   381	      index += 1
   382	      value = Some(args[index])
   383	      value_source = sources[index]
   384	    }
   385	    let mut label : String? = None
   386	    let mut observed : String? = None
   387	    if value is Some(text) {
   388	      if flag == "--provider" &&
   389	        ["docker", "apple", "podman", "kubernetes"].contains(text) {
   390	        label = Some("provider")
   391	        observed = Some(text)
   392	      } else if flag == "--platform" &&
   393	        ["linux/amd64", "linux/arm64"].contains(text) {
   394	        label = Some("platform")
   395	        observed = Some(text)
   396	      } else if flag == "--provider-option" &&
   397	        text.split_once("=") is Some((name, setting)) &&
   398	        name == "SIZE" &&
   399	        observable_size(setting.to_owned()) {
   400	        label = Some("provider-option.SIZE")
   401	        observed = Some(setting.to_owned())
   402	      }
   403	    }
   404	    if label is Some(label) && observed is Some(observed) {
   405	      selected.push({
   406	        "option": label,
   407	        "value": observed,
   408	        "source": flag_source,
   409	        "valueSource": value_source,
   410	      })
   411	    } else {
   412	      withheld += 1
   413	    }
   414	    index += 1
   415	  }
   416	  ({ "selected": selected, "withheldCount": withheld }, withheld > 0)
   417	}
