 303	fn diagnostic_json(
 304	  value : Json,
 305	  environment : Map[String, String],
 306	  protected_secrets : Array[String],
 307	  truncated : Ref[Bool],
 308	  depth : Int32,
 309	  stable_activity~ : Bool = false,
 310	  secret_states~ : Bool = false,
 311	  stable_operation~ : Bool = false,
 312	) -> Json {
 313	  if depth >= 64 {
 314	    truncated.val = true
 315	    return Json::string("[nested evidence omitted]")
 316	  }
 317	  match value {
 318	    Json::Object(values) => {
 319	      let result = Json::empty_object()
 320	      for name, item in values {
 321	        let key = name.to_lower().replace_all(old="_", new="")
 322	        let safe_name = if (
 323	            stable_operation &&
 324	            depth == 0 &&
 325	            ["operationId", "workspaceId"].contains(name)
 326	          ) ||
 327	          (
 328	            stable_activity &&
 329	            [
 330	              "schemaVersion", "observedAt", "activity", "reason", "terminals", "chats",
 331	              "errors", "worktreeId", "agent", "type", "state", "programState", "sessionId",
 332	              "workspaceId", "source", "code", "id", "uid", "context", "provider",
 333	              "identityVerified", "vmStatus", "outcome", "evidence", "evidenceTruncated",
 334	              "workspaces", "discoveryErrors", "action", "failed", "detailsTruncated",
 335	              "error", "autoStop",
 336	            ].contains(name)
 337	          ) {
 338	          name
 339	        } else {
 340	          diagnostic_text(name, environment~, protected_secrets~)
 341	        }
 342	        if field(result, safe_name) is Some(_) {
 343	          truncated.val = true
 344	          continue
 345	        }
 346	        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
 347	          truncated.val = true
 348	        }
 349	        set_field(
 350	          result,
 351	          safe_name,
 352	          if credential_field(name, for_diagnostics=true) ||
 353	            key == "pairingcode" {
 354	            if secret_states &&
 355	              field(item, "state") is Some(Json::String(state)) &&
 356	              ["unset", "empty", "set"].contains(state) {
 357	              let masked : Json = { "state": state }
 358	              if field(item, "value") is Some(_) {
 359	                set_field(masked, "value", Json::string("[redacted]"))
 360	              }
 361	              if field(item, "truncated") == Some(Json::boolean(true)) {
 362	                set_field(masked, "truncated", Json::boolean(true))
 363	                truncated.val = true
 364	              }
 365	              masked
 366	            } else {
 367	              Json::string("[redacted]")
 368	            }
 369	          } else if stable_activity &&
 370	            name == "activity" &&
 371	            (
 372	              item == Json::string("idle") ||
 373	              item == Json::string("active") ||
 374	              item == Json::string("unknown")
 375	            ) {
 376	            item
 377	          } else {
 378	            diagnostic_json(
 379	              item,
 380	              environment,
 381	              protected_secrets,
 382	              truncated,
 383	              depth + 1,
 384	              stable_activity~,
 385	              secret_states~,
 386	              stable_operation~,
 387	            )
 388	          },
 389	        )
 390	      }
 391	      result
 392	    }
 393	    Json::Array(values) =>
 394	      Json::array(
 395	        values.map(item => {
 396	          diagnostic_json(
 397	            item,
 398	            environment,
 399	            protected_secrets,
 400	            truncated,
 401	            depth + 1,
 402	            stable_activity~,
 403	            secret_states~,
 404	            stable_operation~,
 405	          )
 406	        }),
 407	      )
 408	    Json::String(text) => {
 409	      let safe = diagnostic_text(text, environment~, protected_secrets~)
 410	      if safe.has_suffix("\n[error details incomplete or truncated]") {
 411	        truncated.val = true
 412	      }
 413	      Json::string(safe)
 414	    }
 415	    _ => value
 416	  }
 417	}
