420	async fn Progress::line(
557	async fn Progress::read_output(
558	  self : Progress,
559	  reader : @process.ReadFromProcess,
560	  capture~ : Bool,
561	  statuses~ : Bool = false,
562	  messages~ : Bool = false,
563	  raw_messages~ : Bool = false,
564	) -> String {
565	  let output = @buffer.Buffer(size_hint=4096)
566	  let pending = @buffer.Buffer(size_hint=4096)
567	  let mut oversized = false
568	  let mut tail = ""
569	  while reader.read_some(max_len=4096) is Some(chunk) {
570	    if capture {
571	      output.write_bytes(chunk)
572	    } else {
573	      tail += @utf8.decode_lossy(chunk)
574	      if tail.length() > 8192 {
575	        tail = tail[tail.length() - 8192:].to_owned()
576	      }
577	    }
578	    for byte in chunk {
579	      if byte == b'\n' || byte == b'\r' {
580	        if !oversized && pending.length() > 0 {
581	          let line = @utf8.decode(pending.to_bytes()) catch {
582	            _ => {
583	              self.details_truncated = true
584	              ""
585	            }
586	          }
587	          if raw_messages {
588	            self.message(line, debug=false, warning=true, emit=false)
589	          } else if capture {
590	            self.line(line, statuses~, messages~)
591	          } else {
592	            self.stderr_line(line, statuses~, messages~)
593	          }
594	        }
595	        pending.reset()
596	        oversized = false
597	      } else if !oversized {
598	        if pending.length() == 65536 {
599	          pending.reset()
600	          oversized = true
601	          self.details_truncated = true
602	        } else {
603	          pending.write_byte(byte)
604	        }
605	      }
606	    }
607	  }
608	  if !oversized && pending.length() > 0 {
609	    let line = @utf8.decode(pending.to_bytes()) catch {
610	      _ => {
611	        self.details_truncated = true
612	        ""
613	      }
614	    }
615	    let masked = diagnostic_partial_secret(line, self.secrets)
616	    if masked != line {
617	      self.details_truncated = true
618	    }
619	    if raw_messages {
620	      self.message(masked, debug=false, warning=true, emit=false)
621	    } else if capture {
622	      self.line(masked, statuses~, messages~)
623	    } else {
624	      self.stderr_line(masked, statuses~, messages~)
625	    }
626	  }
627	  if capture {
628	    @utf8.decode(output.to_bytes())
629	  } else {
630	    tail
631	  }
632	}

