1644	///|
1645	// A recording grammar, never a replacement for checkout validation. Excludes
1646	// URLs, credential forms, control characters and Git's invalid ref syntax.
1647	fn diagnostic_ref(text : String) -> Bool {
1648	  text.length() <= 1024 &&
1649	  !text.has_prefix("-") &&
1650	  !text.contains("..") &&
1651	  text
1652	  .split("/")
1653	  .iter()
1654	  .all(part => {
1655	    part != "" &&
1656	    !part.has_prefix(".") &&
1657	    !part.has_suffix(".") &&
1658	    !part.has_suffix(".lock")
1659	  }) &&
1660	  text
1661	  .iter()
1662	  .all(c => {
1663	    (c >= 'a' && c <= 'z') ||
1664	    (c >= 'A' && c <= 'Z') ||
1665	    (c >= '0' && c <= '9') ||
1666	    c == '/' ||
1667	    c == '-' ||
1668	    c == '_' ||
1669	    c == '.'
1670	  })
1671	}
