 335	///|
 336	fn workspace_environment(state : Json) -> Map[String, String] {
 337	  let environment = match field(state, "executionEnvironment") {
 338	    Some(Json::Object(values)) => {
 339	      let result : Map[String, String] = Map([])
 340	      for (name, value) in values {
 341	        if value is Json::String(value) {
 342	          result.set(name, value)
 343	        }
 344	      }
 345	      result
 346	    }
 347	    _ => @env.get_env_vars()
 348	  }
 349	  for name in location_variables {
 350	    match field(field(state, "devsyEnv").unwrap_or(Json::null()), name) {
 351	      Some(Json::String(value)) => environment.set(name, value)
 352	      _ => environment.remove(name)
 353	    }
 354	  }
 355	  environment
 356	}
