 366	///|
 367	async fn workspace_program(state : Json, program : String) -> String {
 368	  let cwd = workspace_directory(state).unwrap_or(
 369	    @env.current_dir().unwrap_or("/"),
 370	  )
 371	  if program.has_prefix("/") {
 372	    return program
 373	  }
 374	  if program.contains("/") {
 375	    return cwd + "/" + program
 376	  }
 377	  let path = field(field(state, "devsyEnv").unwrap_or(Json::null()), "PATH")
 378	  let path = match path {
 379	    Some(Json::String(value)) => value
 380	    _ => "/usr/bin:/bin"
 381	  }
 382	  let mut fallback = None
 383	  for directory in path.split(":") {
 384	    let directory = if directory.has_prefix("/") {
 385	      directory.to_owned()
 386	    } else {
 387	      cwd + "/" + directory.to_owned()
 388	    }
 389	    let candidate = directory + "/" + program
 390	    if fallback is None {
 391	      fallback = Some(candidate)
 392	    }
 393	    if transport_access(@utf8.encode(candidate + "\u0000"), 1) == 0 &&
 394	      @fs.kind(candidate) != @fs.FileKind::Directory {
 395	      return candidate
 396	    }
 397	  }
 398	  fallback.unwrap_or(cwd + "/" + program)
 399	}
