 20	async fn ensure_supervisor(initial_workspace? : String) -> Unit {
 21	  let mut phase = "state-directory"
 22	  let mut failure_recorded = false
 23	  errdefer (if !failure_recorded && @async.is_being_cancelled() {
 24	    @async.protect_from_cancel(async fn() {
 25	      save_diagnostic(
 26	        "supervisor-launch",
 27	        "cancelled",
 28	        error_type="cancelled",
 29	        phase~,
 30	      )
 31	    })
 32	  })
 33	  let failure = try {
 34	    let directory = adapter_state_home()
 35	    @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
 36	    phase = "startup-lock"
 37	    let startup = @fs.open(
 38	      directory + "/supervisor-startup.lock",
 39	      mode=ReadWrite,
 40	      create_mode=OpenOrCreate,
 41	      permission=0o600,
 42	    )
 43	    defer startup.close()
 44	    @async.with_timeout(10000, async fn() {
 45	      while !startup.try_lock(Exclusive) {
 46	        @async.sleep(10)
 47	      }
 48	      if @fs.exists(directory + "/shutdown") {
 49	        @fs.remove(directory + "/shutdown")
