 53	          "stateDirectory": directory,
 54	        })
 55	        return
 56	      }
 57	      phase = "launch"
 58	      launch_supervisor(directory, initial_workspace?)
 59	    })
 60	    None
 61	  } catch {
 62	    error => Some(error)
 63	  }
