    38	    [_, "status" | "stop" | "resume" as mode, .. options] =>
    39	      @adapter.bulk(mode, options.to_owned())
    40	    [_, "--help"] => @stdio.stdout.write(@adapter.usage)
    41	    _ => @adapter.usage_error()
    42	  }
