   202	pub async fn supervisor(
   203	  directory : String,
   204	  initial_workspace? : String,
   205	) -> Unit {
   206	  let startup_hold : Ref[@fs.File?] = { val: None, }
   207	  defer (if startup_hold.val is Some(held) { held.close() })
   208	  let mut lock : @fs.File? = None
   209	  defer (if lock is Some(held) { held.close() })
   210	  defer @async.protect_from_cancel(async fn() { finish_diagnostic_recording() })
   211	  let mut failure_recorded = false
   212	  errdefer (if !failure_recorded && @async.is_being_cancelled() {
   213	    @async.protect_from_cancel(async fn() {
   214	      save_diagnostic("supervisor", "cancelled", error_type="cancelled")
   215	    })
   216	  })
   217	  let failure = try {
   218	    guard directory == adapter_state_home() else {
   219	      raise AdapterError("Supervisor state directory mismatch")
   220	    }
   221	    let held = @fs.open(
   222	      directory + "/supervisor.lock",
   223	      mode=ReadWrite,
   224	      create_mode=OpenOrCreate,
   225	      permission=0o600,
   226	    )
   227	    lock = Some(held)
   228	    if !held.try_lock(Exclusive) {
   229	      return
   230	    }
   231	    supervisor_inner(directory, startup_hold, initial_workspace?)
   232	    None
   233	  } catch {
   234	    error => Some(error)
   235	  }
   236	  if failure is Some(error) {
   237	    failure_recorded = true
   238	    save_command_failure("supervisor", error)
   239	    raise error
   240	  }
   241	}
