   420	async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
   421	  let length = if size > 262144L { 262144 } else { size.to_int() }
   422	  let bytes = FixedArray::make(length, b'\x00')
   423	  let read = file.read_at(bytes, position=size - length.to_int64())
   424	  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
   425	  let lines = text.split("\n").to_array()
   426	  let kept = FixedArray::make(lines.length(), false)
   427	  let mut remaining = 65536
   428	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
   429	    if i == 0 && size > length.to_int64() {
   430	      continue
   431	    }
   432	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
   433	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
   434	      100
   435	    } else {
   436	      0
   437	    }
   438	    let length = lines[i].length() + 1 + overhead
   439	    if length <= remaining {
   440	      kept[i] = true
   441	      remaining -= length
   442	    }
   443	  }
   444	  remaining = 65536
   445	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
   446	    if kept[i] || (i == 0 && size > length.to_int64()) {
   447	      continue
   448	    }
   449	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
   450	    let failed = field(event, "errorType") is Some(_) ||
   451	      (match field(event, "status") {
   452	        Some(Json::String(status)) =>
   453	          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
   454	            status,
   455	          )
   456	        _ => false
   457	      })
   458	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
   459	      100
   460	    } else {
   461	      0
   462	    }
   463	    let length = lines[i].length() + 1 + overhead
   464	    if failed && length <= remaining {
   465	      kept[i] = true
   466	      remaining -= length
   467	    }
   468	  }
   469	  let dropped_runs : Map[String, Bool] = Map([])
   470	  for i in 0..<(lines.length() - 1) {
   471	    if !kept[i] {
   472	      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
   473	      if field(event, "runId") is Some(Json::String(id)) {
   474	        dropped_runs.set(id, true)
   475	      }
   476	    }
   477	  }
   478	  let result = @buffer.Buffer(size_hint=131072)
   479	  for i in 0..<lines.length() {
   480	    if kept[i] {
   481	      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
   482	      if field(event, "runId") is Some(Json::String(id)) {
   483	        set_field(
   484	          event,
   485	          "runCompleteness",
   486	          Json::string(
   487	            if dropped_runs.contains(id) ||
   488	              field(event, "runCompleteness") == Some(Json::string("partial")) {
   489	              "partial"
   490	            } else {
   491	              "unknown"
   492	            },
   493	          ),
   494	        )
   495	        set_field(event, "runMissingReason", Json::string("retention_limit"))
   496	        result.write_string_utf8(event.stringify() + "\n")
   497	      } else {
   498	        result.write_string_utf8(lines[i].to_owned() + "\n")
   499	      }
   500	    }
   501	  }
   502	  @utf8.decode_lossy(result.to_bytes())
   503	}
