420	async fn Progress::line(
421	  self : Progress,
422	  line : String,
423	  statuses~ : Bool,
424	  messages~ : Bool,
425	) -> Unit {
426	  if line.trim() == "" {
427	    return
428	  }
429	  let event = @json.parse(line) catch { _ => Json::null() }
430	  if event != Json::null() {
431	    let protected_values : DiagnosticProtectedValues = {
432	      secrets: [],
433	      visited: 0,
434	      incomplete: false,
435	    }
436	    diagnostic_protected_values(event, protected_values, line, false)
437	    if protected_values.incomplete ||
438	      self.secrets.length() + protected_values.secrets.length() > 1024 {
439	      self.protection_incomplete = true
440	      self.details_truncated = true
441	    } else {
442	      for secret in protected_values.secrets {
443	        add_protected_secret(self.secrets, secret)
444	      }
445	      self.secrets.sort_by((a, b) => b.length().compare(a.length()))
446	    }
447	  }
448	  if field(event, "kind") == Some(Json::string("status")) {
449	    if field(event, "state") == Some(Json::string("failed")) &&
450	      field(event, "error") is Some(error) {
451	      for name in ["message", "hint"] {
452	        if field(error, name) is Some(Json::String(text)) {
453	          self.message(
454	            text,
455	            debug=false,
456	            warning=true,
457	            emit=messages || statuses,
458	          )
459	        }
460	      }
461	    }
462	    if statuses || messages {
463	      self.status(event)
464	    }
465	    return
466	  }
467	  // Result envelopes and arbitrary structured responses are never log text.
468	  if field(event, "kind") == Some(Json::string("result")) {
469	    return
470	  }
471	  if event is Json::Object(_) {
472	    let kind = field(event, "kind")
473	    guard kind == None ||
474	      kind == Some(Json::string("log")) ||
475	      kind == Some(Json::string("error")) else {
476	      return
477	    }
478	    let message = match field(event, "msg") {
479	      Some(value) => Some(value)
480	      None =>
481	        match field(event, "message") {
482	          Some(value) => Some(value)
483	          None =>
484	            match field(event, "error") {
485	              Some(Json::Object(_) as value) => field(value, "message")
486	              value => value
487	            }
488	        }
489	    }
490	    guard message is Some(Json::String(text)) else { return }
491	    let level = field(event, "level")
492	    self.message(
493	      text,
494	      debug=level == Some(Json::string("debug")) ||
495	        level == Some(Json::string("trace")),
496	      warning=kind == Some(Json::string("error")) ||
497	        level == Some(Json::string("warn")) ||
498	        level == Some(Json::string("error")),
499	      emit=messages || (statuses && kind != None),
500	    )
501	  } else {
502	    if event != Json::null() {
503	      return
504	    }
505	    // Malformed JSON and binary output are not a safe free-text fallback.
506	    let text = line.trim().to_owned()
507	    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
508	      self.message(text, debug=false, warning=true, emit=messages)
509	      return
510	    }
511	    if text.has_prefix("{") || text.has_prefix("[") {
512	      self.details_truncated = true
513	      return
514	    }
515	    self.message(
516	      text,
517	      debug=text.contains(" DEBUG ") ||
518	        text.contains(" TRACE ") ||
519	        text.has_prefix("DEBUG ") ||
520	        text.has_prefix("TRACE "),
521	      warning=text.contains(" WARN ") ||
522	        text.contains(" ERROR ") ||
523	        text.has_prefix("WARN ") ||
524	        text.has_prefix("ERROR "),
525	      emit=messages,
526	    )
527	  }
528	}
