1355	///|
1356	fn DiagnosticCapture::new(limit : Int32) -> DiagnosticCapture {
1357	  {
1358	    output: @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 }),
1359	    limit,
1360	    truncated: false,
1361	    finished: false,
1362	  }
1363	}
