1365	///|
1366	async fn DiagnosticCapture::read(
1367	  self : DiagnosticCapture,
1368	  reader : @process.ReadFromProcess,
1369	) -> Unit {
1370	  try {
1371	    while reader.read_some(max_len=4096) is Some(chunk) {
1372	      let remaining = self.limit - self.output.length()
1373	      let count = if chunk.length() < remaining {
1374	        chunk.length()
1375	      } else {
1376	        remaining
1377	      }
1378	      if count > 0 {
1379	        self.output.write_bytes(chunk[:count])
1380	      }
1381	      if count < chunk.length() {
1382	        self.truncated = true
1383	      }
1384	    }
1385	  } catch {
1386	    error =>
1387	      if @async.is_being_cancelled() {
1388	        raise error
1389	      } else {
1390	        self.truncated = true
1391	      }
1392	  }
1393	  self.finished = true
1394	}
