1397	async fn wait_diagnostic_captures(captures : Array[DiagnosticCapture]) -> Unit {
1398	  @async.with_timeout(250, async fn() {
1399	    while captures.iter().any(capture => !capture.finished) {
1400	      @async.sleep(5)
1401	    }
1402	  }) catch {
1403	    error => if @async.is_being_cancelled() { raise error }
1404	  }
1405	}
