   692	    } else if !discovery_errors.is_empty() {
   693	      "partial"
   694	    } else {
   695	      "success"
   696	    },
   697	    error_type?=if !discovery_errors.is_empty() {
   698	      Some("saved_state_invalid")
   699	    } else {
