   705	      .any(result => {
   706	        field(result, "evidenceTruncated") == Some(Json::boolean(true))
   707	      }),
   708	    evidence_stable_activity=true,
   709	    protected_secrets=secrets,
   710	    recording=recording_allowed.val,
   711	  )
   712	
   713	  failures
   714	}

