   393	        ["linux/amd64", "linux/arm64"].contains(text) {
   394	        label = Some("platform")
   395	        observed = Some(text)
   396	      } else if flag == "--provider-option" &&
   397	        text.split_once("=") is Some((name, setting)) &&
   398	        name == "SIZE" &&
   399	        observable_size(setting.to_owned()) {
   400	        label = Some("provider-option.SIZE")
   401	        observed = Some(setting.to_owned())
   402	      }
   403	    }
   404	    if label is Some(label) && observed is Some(observed) {
   405	      selected.push({
   406	        "option": label,
   407	        "value": observed,
   408	        "source": flag_source,
   409	        "valueSource": value_source,
   410	      })
   411	    } else {
   412	      withheld += 1
   413	    }
   414	    index += 1
   415	  }
   416	  ({ "selected": selected, "withheldCount": withheld }, withheld > 0)
   417	}
  1613	fn diagnostic_value(value : String?, kind : DiagnosticValueKind) -> Json {
  1614	  match value {
  1615	    None => { "state": "unset" }
  1616	    Some("") => { "state": "empty" }
  1617	    Some(text) => {
  1618	      let valid = match kind {
  1619	        Commit => valid_commit(text)
  1620	        Workspace => valid_workspace_id(text)
  1621	        Identity => text.length() <= 128 && valid_context(text)
  1622	        RefName => diagnostic_ref(text)
  1623	      }
  1624	      let credential_form = text
  1625	        .split("/")
  1626	        .iter()
  1627	        .any(part => {
  1628	          [
  1629	            "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "glpat-", "sk-",
  1630	            "eyJ",
  1631	          ]
  1632	          .iter()
  1633	          .any(prefix => part.has_prefix(prefix))
  1634	        })
  1635	      if valid && !credential_form {
  1636	        { "state": "valid", "value": text }
  1637	      } else {
  1638	        { "state": "invalid" }
  1639	      }
  1640	    }
  1641	  }
